"""
Execution-grounded verification of agent-authored workspaces.

This module implements the ExecutionHarness which verifies code by actually
running it (parsing, installing, importing, testing) rather than relying on
textual analysis or file counts.
"""

import ast
import os
import sys
import subprocess
import tempfile
import shutil
import time
import re
import json
import tomllib
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Any, Tuple, Iterable

# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Import artifacts module if available, otherwise define minimal fallbacks
# The prompt implies artifacts.py is being implemented in parallel.
# We assume it exists in the same package structure or we import it.
try:
    from hae.evaluation.artifacts import (
        is_generated_path,
        is_malformed_path,
        sanitize_path,
        filter_bundle,
        partition_bundle,
        count_source_files,
        EXCLUDED_DIR_SEGMENTS,
        EXCLUDED_DIR_SUFFIXES
    )
except ImportError:
    # Fallback definitions if artifacts.py is not yet available or import fails
    # These match the specification provided in the prompt for artifacts.py
    EXCLUDED_DIR_SEGMENTS = ('.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints')
    EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')

    def is_generated_path(path: str) -> bool:
        parts = path.replace('\\', '/').split('/')
        for part in parts:
            if part in EXCLUDED_DIR_SEGMENTS:
                return True
            if any(part.endswith(s) for s in EXCLUDED_DIR_SUFFIXES):
                return True
        return False

    def is_malformed_path(path: str) -> bool:
        if not path:
            return True
        if path != path.strip():
            return True
        if '*' in path or '`' in path:
            return True
        if path.startswith('-'):
            return True
        if path.endswith('.') or path.endswith('~'):
            return True
        return False

    def sanitize_path(path: str) -> str:
        path = path.strip()
        path = path.replace('*', '').replace('`', '')
        if path.startswith('-'):
            path = path[1:]
        if path.endswith('.') or path.endswith('~'):
            path = path[:-1]
        return path

    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return {k: v for k, v in bundle.items() if not is_generated_path(k) and not is_malformed_path(k)}

    def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
        authored = {}
        generated = {}
        malformed = {}
        for k, v in bundle.items():
            if is_generated_path(k):
                generated[k] = v
            elif is_malformed_path(k):
                malformed[k] = v
            else:
                authored[k] = v
        return authored, generated, malformed

    def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
        count = 0
        for path in bundle.keys():
            if any(path.endswith(s) for s in suffixes):
                count += 1
        return count


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed = [g for g in evaluated if g.passed]
        return len(passed) / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files}, Python Files: {self.python_files}")
        lines.append(f"Pass Rate: {self.pass_rate:.2%}")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append("Gates:")
        for g in self.gates:
            lines.append(f"  [{g.status.upper():7}] {g.name:10} ({g.method}): {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "pass_rate": self.pass_rate,
            "gate_status": self.gate_status
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to find fenced code blocks with optional language and optional filename hint
    # Common patterns:
    # ```python
    # ```path/to/file.py
    # ```python path/to/file.py
    # We look for blocks that might contain a filename in the info string or infer from context.
    # Since standard markdown doesn't strictly enforce filenames, we look for:
    # 1. Info string containing a .py extension
    # 2. Or just assume sequential naming if no filename is present? 
    # The spec says "path->content map". If no path is provided, we can't map it.
    # However, often agents write:
    # ```python
    # # path: src/main.py
    # ...
    # ```
    # Or use the fence info string.

    blocks = {}
    # Pattern: ```[lang] [path] ... ```
    # We'll try to extract a path from the info string.
    pattern = r"```(?:\s*(\S+))?\s*\n(.*?)\n```"

    matches = re.finditer(pattern, text, re.DOTALL)

    counter = 0
    for match in matches:
        info = match.group(1) or ""
        content = match.group(2)

        # Try to find a path in the info string
        path = None
        if info:
            # Check if info string looks like a path
            if '.' in info and not info.startswith('python'): # e.g. "main.py" or "src/main.py"
                path = info
            elif info.startswith('python'):
                # Maybe "python src/main.py"
                parts = info.split()
                for p in parts:
                    if p.endswith('.py'):
                        path = p
                        break

        # If no path in info, check first line of content for a comment like "# path: ..."
        if not path:
            lines = content.split('\n')
            if lines:
                first_line = lines[0].strip()
                # Look for common path indicators
                if first_line.startswith('#') and ('path' in first_line.lower() or '.py' in first_line):
                    # Extract path
                    # e.g. "# path: src/main.py" or "# src/main.py"
                    parts = first_line.split()
                    for p in parts:
                        if p.endswith('.py'):
                            path = p
                            break

        if not path:
            # Fallback: generate a unique name
            path = f"extracted_block_{counter}.py"
            counter += 1

        # Sanitize path
        path = sanitize_path(path)
        if not path:
            continue

        blocks[path] = content

    return blocks


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        # Try to get bundle from workspace object
        if workspace is not None:
            # Assume workspace has a method to get files or is a dict
            if isinstance(workspace, dict):
                bundle = workspace
                source = 'dict'
            elif hasattr(workspace, 'get_files'):
                bundle = workspace.get_files()
                source = 'workspace'
            elif hasattr(workspace, 'files'):
                bundle = workspace.files
                source = 'workspace'
            elif hasattr(workspace, 'list_files'):
                # Some workspaces return list of paths, need to read them
                # This is tricky without knowing the workspace API fully.
                # Assuming standard dict-like behavior for now.
                pass

        # If bundle is empty, try extracting from deliverable text
        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        if not bundle:
            # Empty workspace
            return self._create_empty_report(source)

        return self.verify_bundle(bundle, source=source)

    def _create_empty_report(self, source: str) -> VerificationReport:
        gates = [
            GateResult(name='syntax', status=FAILED, method='ast.parse', detail='No Python files found'),
            GateResult(name='build', status=FAILED, method='metadata', detail='No packaging metadata found'),
            GateResult(name='smoke', status=FAILED, method='import', detail='No modules to import'),
            GateResult(name='tests', status=FAILED, method='pytest', detail='No tests found'),
            GateResult(name='telemetry', status=FAILED, method='ast', detail='No telemetry usage found'),
        ]
        failed_count = sum(1 for g in gates if g.status == FAILED)
        return VerificationReport(
            gates=gates,
            score_penalty=failed_count * self.penalty_per_gate,
            authored_files=0,
            python_files=0,
            source=source
        )

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter bundle to remove generated/malformed paths
        authored_bundle = filter_bundle(bundle)

        # Count files
        authored_files = len(authored_bundle)
        python_files = count_source_files(authored_bundle, suffixes=('.py',))

        # Create temp directory
        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files to disk
            for path, content in authored_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            # Run gates
            return self.verify_directory(tmpdir, authored=authored_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory
            authored = {}
            for root, dirs, files in os.walk(workdir):
                # Filter out excluded dirs
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.relpath(os.path.join(root, d), workdir))]
                for file in files:
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        full_path = os.path.join(root, file)
                        try:
                            with open(full_path, 'r', encoding='utf-8') as f:
                                authored[rel_path] = f.read()
                        except Exception:
                            pass

        authored_files = len(authored)
        python_files = count_source_files(authored, suffixes=('.py',))

        gates = []

        # 1. Syntax Gate
        gates.append(self._gate_syntax(workdir, authored))

        # 2. Build Gate
        gates.append(self._gate_build(workdir, authored))

        # 3. Smoke Gate
        gates.append(self._gate_smoke(workdir, authored))

        # 4. Tests Gate
        gates.append(self._gate_tests(workdir, authored))

        # 5. Telemetry Gate
        gates.append(self._gate_telemetry(workdir, authored))

        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files,
            python_files=python_files,
            source=source
        )

    def _gate_syntax(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()
        py_files = [p for p in authored.keys() if p.endswith('.py')]

        if not py_files:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast.parse',
                detail='No Python files found',
                duration_s=time.time() - start
            )

        errors = []
        for path in py_files:
            content = authored[path]
            try:
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{path}: {e}")

        duration = time.time() - start
        if errors:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast.parse',
                detail=f"Syntax errors in {len(errors)} files: {errors[0]}",
                duration_s=duration,
                evidence={'errors': errors}
            )

        return GateResult(
            name='syntax',
            status=PASSED,
            method='ast.parse',
            detail=f"All {len(py_files)} Python files parsed successfully",
            duration_s=duration
        )

    def _gate_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Check for packaging metadata
        metadata_files = ['pyproject.toml', 'setup.py', 'setup.cfg']
        found_metadata = None

        for mf in metadata_files:
            if mf in authored:
                found_metadata = mf
                break

        if not found_metadata:
            return GateResult(
                name='build',
                status=FAILED,
                method='metadata',
                detail='No packaging metadata (pyproject.toml, setup.py, setup.cfg) found',
                duration_s=time.time() - start
            )

        # Validate pyproject.toml if present
        if 'pyproject.toml' in authored:
            content = authored['pyproject.toml']
            try:
                data = tomllib.loads(content)
                # Must contain at least one of [project], [build-system], or [tool]
                if not any(key in data for key in ['project', 'build-system', 'tool']):
                    return GateResult(
                        name='build',
                        status=FAILED,
                        method='tomllib',
                        detail='pyproject.toml is valid TOML but missing required tables ([project], [build-system], or [tool])',
                        duration_s=time.time() - start
                    )
            except Exception as e:
                err_msg = str(e)
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='tomllib',
                    detail=f'pyproject.toml is invalid: {err_msg}',
                    duration_s=time.time() - start
                )

        # Try pip install
        # Check if pip is available
        try:
            subprocess.run([self.python_executable, '-m', 'pip', '--version'], 
                           capture_output=True, timeout=10, check=True)
        except Exception:
            return GateResult(
                name='build',
                status=SKIPPED,
                method='pip',
                detail='pip not available or failed to run',
                duration_s=time.time() - start
            )

        # Run pip install -e . --no-deps --no-build-isolation
        try:
            result = subprocess.run(
                [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation'],
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )
            duration = time.time() - start
            if result.returncode == 0:
                return GateResult(
                    name='build',
                    status=PASSED,
                    method='pip',
                    detail='Package installed successfully',
                    duration_s=duration
                )
            else:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='pip',
                    detail=f'pip install failed: {result.stderr}',
                    duration_s=duration,
                    evidence={'stderr': result.stderr, 'stdout': result.stdout}
                )
        except subprocess.TimeoutExpired:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip',
                detail='pip install timed out',
                duration_s=time.time() - start
            )
        except Exception as e:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip',
                detail=f'pip install error: {e}',
                duration_s=time.time() - start
            )

    def _gate_smoke(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Find non-test authored modules
        # Exclude test files
        modules = []
        for path in authored.keys():
            if not path.endswith('.py'):
                continue
            if 'test' in os.path.basename(path).lower():
                continue
            # Convert path to module name
            # e.g. src/main.py -> src.main or main depending on structure
            # We'll try to import the file directly by path in a subprocess

            # Determine module name relative to workdir or src
            # If file is in src/, we might need to add src to path
            modules.append(path)

        if not modules:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import',
                detail='No importable non-test modules found',
                duration_s=time.time() - start
            )

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        python_path = f"{workdir}:{src_dir}"
        if os.name == 'nt':
            python_path = f"{workdir};{src_dir}"

        env = os.environ.copy()
        env['PYTHONPATH'] = python_path

        # Try importing each module
        import_errors = []
        module_not_found_errors = []

        for path in modules:
            # Convert path to importable module name
            # Remove .py
            mod_path = path[:-3]
            # Replace slashes with dots
            mod_name = mod_path.replace('/', '.').replace('\\', '.')

            # If it's in src/, the module name might be just the part after src/
            # But since we added src to PYTHONPATH, we can import it as if it's top-level
            # Actually, if we have src/main.py, and src is in PYTHONPATH, we import 'main'
            # If we have main.py in root, and root is in PYTHONPATH, we import 'main'

            # Let's try to import the module name derived from the path relative to workdir
            # If path is src/main.py, mod_name is src.main. But if src is in path, we should import main.
            # This is complex. Let's try importing the file directly using importlib in a subprocess.

            code = f"""
import sys
import importlib.util
import os

path = r"{os.path.join(workdir, path)}"
try:
    spec = importlib.util.spec_from_file_location("module_under_test", path)
    module = importlib.util.module_from_spec(spec)
    sys.modules["module_under_test"] = module
    spec.loader.exec_module(module)
    print("SUCCESS")
except ModuleNotFoundError as e:
    print(f"MODULE_NOT_FOUND: {e}")
except Exception as e:
    print(f"ERROR: {e}")
"""
            try:
                result = subprocess.run(
                    [self.python_executable, '-c', code],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )
                output = result.stdout.strip()
                if output == "SUCCESS":
                    continue
                elif output.startswith("MODULE_NOT_FOUND:"):
                    module_not_found_errors.append(f"{path}: {output}")
                else:
                    import_errors.append(f"{path}: {output}")
            except Exception as e:
                import_errors.append(f"{path}: Execution error {e}")

        duration = time.time() - start

